import json
import sys

def subset_file(input_path, output_path, max_qas=10):
    with open(input_path) as f:
        data = json.load(f)
    # SQuAD: {"data": [{"paragraphs": [{"qas": [ ... ]}]}]}
    qa_count = 0
    new_data = []
    for article in data['data']:
        new_article = {'title': article.get('title', None), 'paragraphs': []}
        for para in article['paragraphs']:
            new_para = {'context': para['context'], 'qas': []}
            for qa in para['qas']:
                if qa_count < max_qas:
                    new_para['qas'].append(qa)
                    qa_count += 1
                if qa_count >= max_qas:
                    break
            if new_para['qas']:
                new_article['paragraphs'].append(new_para)
            if qa_count >= max_qas:
                break
        if new_article['paragraphs']:
            new_data.append(new_article)
        if qa_count >= max_qas:
            break
    out = {'version': data.get('version', '1.1'), 'data': new_data}
    with open(output_path, 'w') as f:
        json.dump(out, f)

if __name__ == '__main__':
    subset_file(sys.argv[1], sys.argv[2], max_qas=10)

